601	    fn from_mmap(mmap: Arc<Mmap>) -> Result<Self> {
602	        let data = &mmap[..];
603	        if data.len() < (HEADER_LEN + FOOTER_LEN) as usize {
604	            return Err(StorageError::WalCorrupt(0, "segment file too small".into()));
605	        }
606	
607	        // Validate footer magic
608	        let footer_start = data.len() - FOOTER_LEN as usize;
609	        let magic_end_offset = data.len() - 4;
610	        if &data[magic_end_offset..] != SEG_MAGIC_END {
611	            return Err(StorageError::InvalidMagic {
612	                expected: SEG_MAGIC_END,
613	                actual: data[magic_end_offset..].to_vec(),
614	            });
615	        }
