617	        // Read footer
618	        let mut footer_cur = std::io::Cursor::new(&data[footer_start..]);
619	        let section_table_offset = footer_cur.read_u64::<LittleEndian>()?;
620	        let stored_total_crc = footer_cur.read_u32::<LittleEndian>()?;
621	
622	        // Verify total CRC (everything except footer)
623	        let mut hasher = Crc32Hasher::new();
