1527	/// Outcome of parsing one raw frame at `off` in a fully-read WAL file.
1528	enum RawFrame<'a> {
1529	    /// `off` is exactly the end of the buffer — clean end of file.
1530	    End,
1531	    /// A CRC-valid frame: `(seq_no, op_code, payload, end_offset)`.
1532	    Frame {
1533	        seq_no: SeqNo,
1534	        op_code: u8,
1535	        payload: &'a [u8],
1536	        end: usize,
1537	    },
1538	    /// The bytes at `off` do not form a complete valid frame (truncated
1539	    /// header/payload, implausible length, or CRC mismatch).
1540	    Corrupt,
1541	}
